async function buyPlan(e){const t=localStorage.getItem("cb_token");if(!t){alert("Please login first.");return}try{const n=await(await fetch("https://api.buildskil.com/api/membership/update",{method:"PUT",headers:{"Content-Type":"application/json",Authorization:`Bearer ${t}`},body:JSON.stringify({plan:e})})).json();if(!n.success){alert(n.message);return}alert("Membership updated successfully!"),location.reload()}catch(r){console.error(r),alert("Server error.")}}function updateCurrentPlan(e){document.querySelectorAll(".btn").forEach(t=>{t.disabled=!1,t.textContent="Upgrade"}),e==="free"&&(document.querySelector(".free-btn").textContent="Current Plan",document.querySelector(".free-btn").disabled=!0),e==="small"&&(document.querySelector(".small-btn").textContent="Current Plan",document.querySelector(".small-btn").disabled=!0),e==="big"&&(document.querySelector(".big-btn").textContent="Current Plan",document.querySelector(".big-btn").disabled=!0)}
